"use client";
import Link from "next/link";
import { Story } from '@/components/story/story';
import { Chapter, Beat, Kicker, Title, Body, Note } from '@/components/story/chapter';
import type { StoryBundle, PieceProps, FaceDef } from '@/components/story/types';
import { blankFormation, type Pose, type Formation } from '@/lib/story/formation';
import type { StoryDef } from '@/lib/story/story';
import { looks } from '../looks';

type Kind = 'fixture' | 'sensor' | 'harness';
const names = {fixture:'01 / The bring-up fixture',sensor:'02 / The sensor, opened',harness:'03 / The observation path'};
const questions = {fixture:'What does the bench let me claim?',sensor:'What does a battery-life estimate actually tell us?',harness:'How does a firmware decision meet a physical observation?'};
const mids = {fixture:'Six tested. Forty assembled.',sensor:'Six samples on the bench.',harness:'Sleep. Measure. Transmit.'};
const bodies = {
 fixture:['I’m Ada Mensah. I wrote Mosslink’s firmware, scheduled its power states and built its bring-up fixture.','Forty engineering samples were assembled. Six were tested on the bench. The six bright sockets count that subset; this is an explanatory layout, not the actual fixture.','A firmware decision needs a physical observation. A projection and an observed run support different claims.'],
 sensor:['I’m Ada Mensah. My work on Mosslink was firmware, power-state scheduling and a bring-up fixture. The PCB and analogue front end were designed by my colleague.','These six simplified bodies count the six engineering samples tested on the bench. Forty were assembled; none went to customers.','Two years is a projection from bench currents and an assumed reporting cycle. The longest run was 72 hours. There is no two-year field endurance evidence.'],
 harness:['I’m Ada Mensah. State tables, timing diagrams and current traces are my working documents. I wrote the firmware and built the bring-up fixture for Mosslink.','Three ordered pairs show a teaching sequence only. They do not show recovered firmware, wiring, durations or current values.','A current trace showed the radio awake after a failed transmission. The cause and later resolution are unconfirmed. An observation is where the next question begins.']
};
function Fixture({material}:PieceProps){return <group><mesh><boxGeometry args={[1,.92,.23]}/><meshStandardMaterial color="#334940" roughness={.65}/></mesh><mesh position={[0,0,.122]} material={material}><planeGeometry args={[1,.92]}/></mesh>{[-.43,.43].map(x=><mesh key={x} position={[x,0,.18]}><boxGeometry args={[.025,.8,.09]}/><meshStandardMaterial color="#b1bbb4" metalness={.6} roughness={.4}/></mesh>)}</group>}
function Sensor({material}:PieceProps){return <group><mesh><boxGeometry args={[.93,.94,.3]}/><meshStandardMaterial color="#334940" roughness={.65}/></mesh><mesh position={[0,0,.155]} material={material}><planeGeometry args={[.89,.89]}/></mesh>{[-.31,.31].map(x=><mesh key={x} position={[x,-.48,0]}><cylinderGeometry args={[.04,.04,.15,12]}/><meshStandardMaterial color="#b2a077" metalness={.7} roughness={.4}/></mesh>)}</group>}
function Harness({material}:PieceProps){return <group><mesh rotation={[Math.PI/2,0,0]}><cylinderGeometry args={[.43,.43,.32,32]}/><meshStandardMaterial color="#334940" roughness={.65}/></mesh><mesh position={[0,0,.17]} material={material}><circleGeometry args={[.4,32]}/></mesh><mesh position={[0,-.43,-.02]}><boxGeometry args={[.22,.35,.2]}/><meshStandardMaterial color="#a19374" metalness={.65} roughness={.4}/></mesh></group>}
const pose=(x:number,y:number,z=0,w=1,h=1,rz=0):Pose=>({position:[x,y,z],rotation:[0,0,rz],size:[w,h]});
function form(pieces:Pose[], kind:Kind):Formation{return {...blankFormation(pieces.length),pieces,span:kind==='fixture'?5.3:4.6,rise:kind==='fixture'?5:4.4,anchor:[.48,.18],turn:[-.18,-.22],near:5,floor:-3.4};}
function make(kind:Kind):StoryBundle {
 const count=kind==='fixture'?8:6;
 const story:StoryDef={pieces:count,chapters:['opening','middle','close'].map((id,i)=>({id,number:i+1,name:['Set up','Observe','Conclude'][i],role:i===0?'opening':i===1?'what':'close',beats:[{id:id+'.pose',height:i===0?1.3:1.25}]}))};
 let opening:Pose[],middle:Pose[],close:Pose[];
 if(kind==='fixture'){
  opening=[pose(0,1.65,0,3.65,.4),pose(0,-1.65,0,3.65,.4),pose(-1.65,0,.03,3.65,.4,Math.PI/2),pose(1.65,0,.03,3.65,.4,Math.PI/2),pose(0,.92,.06,2.2,.34),pose(0,-.92,.06,2.2,.34),pose(-.92,0,.09,2.2,.34,Math.PI/2),pose(.92,0,.09,2.2,.34,Math.PI/2)];
  middle=Array.from({length:8},(_,i)=>pose(0,(i-3.5)*.57,0,3.5,.48));
  close=opening;
 } else if(kind==='sensor'){
  opening=Array.from({length:6},(_,i)=>pose(0,(i-2.5)*.46,0,2,.48));
  middle=Array.from({length:6},(_,i)=>pose((i%2-.5)*1.75,(1-Math.floor(i/2))*1.4,0,1.2,1.1));
  close=Array.from({length:6},(_,i)=>pose((i<3?-1:1)*1.15,(1-i%3)*.65,0,1.55,.55));
 }else{
  opening=Array.from({length:6},(_,i)=>pose(Math.sin(i*.8)*.7,(i-2.5)*.6,i*.04,.8,.8,(i-2.5)*.12));
  middle=Array.from({length:6},(_,i)=>pose((i%2-.5)*1.1,(1-Math.floor(i/2))*1.35,0,.9,.9));
  close=Array.from({length:6},(_,i)=>pose((i<3?-1:1)*1.2,(1-i%3)*.9,0,.85,.85));
 }
 const faces:FaceDef[]=story.chapters.flatMap((ch,beat)=>Array.from({length:count},(_,i)=>({id:ch.id+'-'+i,beat:ch.beats[0].id,piece:i,draw(ctx,w,h){
  ctx.fillStyle='#334940';ctx.fillRect(0,0,w,h);
  if(kind==='fixture')for(let j=0;j<5;j++){const on=beat===1&&i*5+j<6;ctx.beginPath();ctx.ellipse(w*(.15+j*.175),h*.5,w*.04,h*.29,0,0,Math.PI*2);ctx.fillStyle=on?'#e7b96a':'#122b24';ctx.fill();ctx.strokeStyle='#b7c6b8';ctx.lineWidth=h*.025;ctx.stroke();}
  else{ctx.strokeStyle='#9fae9c';ctx.lineWidth=w*.025;ctx.strokeRect(w*.17,h*.17,w*.66,h*.66);ctx.fillStyle='#e7b96a';ctx.beginPath();ctx.arc(w*.5,h*.5,w*.1,0,Math.PI*2);ctx.fill();if(kind==='harness'&&beat===1){ctx.fillStyle='#f8edd5';ctx.font=`bold ${w*.13}px system-ui`;ctx.textAlign='center';ctx.fillText(['SLEEP','MEASURE','TRANSMIT'][Math.floor(i/2)],w*.5,h*.78);}}
 }})));
 return {story,formations:{'opening.pose':{rest:form(opening,kind)},'middle.pose':{rest:form(middle,kind)},'close.pose':{rest:form(close,kind)}},faces,looks:[looks[0]],copy:{railLabel:'Sketch chapters',lookLabel:'Appearance'},Piece:kind==='fixture'?Fixture:kind==='sensor'?Sensor:Harness};
}
const bundles={fixture:make('fixture'),sensor:make('sensor'),harness:make('harness')};
function Concept({kind}:{kind:Kind}){const bundle=bundles[kind];return <main className="concept"><nav className="concept-nav" aria-label="Concepts"><Link prefetch={false} href="/">Concepts</Link><Link prefetch={false} href="/sketch/fixture">Fixture</Link><Link prefetch={false} href="/sketch/sensor">Sensor</Link><Link prefetch={false} href="/sketch/harness">Harness</Link></nav><Story bundle={bundle}>{bundle.story.chapters.map((ch,i)=><Chapter key={ch.id} id={ch.id}><Beat story={bundle.story} id={ch.beats[0].id} fallback={<p>{kind==='fixture'?'● ● ● ● ● / ● ○ ○ ○ ○ / 30 further unlit sockets':kind==='sensor'?'● ● / ● ● / ● ●':'Sleep → Measure → Transmit (teaching sequence)'}</p>}><Kicker number={i+1}>{names[kind]} · {ch.name}</Kicker><Title as={i===0?'h1':'h2'} id={ch.id+'-title'}>{i===0?questions[kind]:i===1?mids[kind]:kind==='sensor'?'Projection ≠ observed run.':'Observe before claiming.'}</Title><Body>{bodies[kind][i]}</Body><Note>Concept sketch · Explanatory geometry; not actual hardware, wiring or measured data.</Note>{i===0&&<p className="sketch-links"><a href="#middle">See the evidence</a> · <a href="mailto:ada@example.com">Email Ada</a></p>}{i===2&&<p><a href="mailto:ada@example.com">ada@example.com</a> · <Link prefetch={false} href="/">Compare concepts</Link></p>}</Beat></Chapter>)}</Story></main>}
export const FixtureSketch=()=> <Concept kind="fixture"/>;
export const SensorSketch=()=> <Concept kind="sensor"/>;
export const HarnessSketch=()=> <Concept kind="harness"/>;
import type { StoryBundle } from "@/components/story/types";
import { story } from "./story";
import { formations } from "./formations";
import { faces } from "./faces";
import { looks } from "./looks";
import { copy } from "./copy";
import { extras } from "./extras";
import { links } from "./links";

export const bundle = { story, formations, faces, looks, copy, extras, links, defaultLook: "light" } satisfies StoryBundle;
export const copy = {
  lang: "en",
  metadata: { title: "Storyfolio | A plain story", description: "A small story for testing the Storyfolio scroll engine." },
  railLabel: "Chapters",
  lookLabel: "Appearance",
  fpsLabel: "Frames per second",
  skipLabel: "Skip to the ending",
  backLabel: "Gather again",
  pictureAlt: "Seven cards opened into a fan, a static version of the scene.",
  faceWords: ["Gather", "Open", "Whole", "One", "Story", "Seven", "Pieces"],
  beats: {
    "opening.gather": {
      title: "One story, seven pieces.",
      body: "This is the engine's test story. Scroll to bring seven scattered cards together, open them, and return them to a whole.",
      note: "The first beat gathers as you scroll. Gather, Open, Whole, One, Story, Seven and Pieces are the words on the cards.",
    },
    "middle.fan": {
      title: "Room to see each piece.",
      body: "The same seven cards open into a fan. A simple line arrives with this chapter, loaded only when you come near it.",
      note: "This schematic tests a chapter's extra shape. The text and the flat illustration also explain it without a canvas.",
    },
    "close.whole": {
      title: "The pieces belong together.",
      body: "The cards close into one stack. The story, its text and its links stay readable when the scene cannot run.",
      note: "The link on the front card is an ordinary keyboard-accessible link. The same destination is here in the text.",
    },
  },
};
"use client";
import { useEffect, useMemo, useRef, type ReactNode, type RefObject } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { atRest, blankFormation, lerp, mixFormation, swing, type Formation, type Pose, type Vec3 } from "@/lib/story/formation";
import { bandFit, bandShare, cameraDistance, overAnchor, overScale, roomBeside, stageLift, viewHalf, type Stage } from "@/lib/story/camera";
import { pieceOnScreen } from "@/lib/story/overlay";
import { beatsOf } from "@/lib/story/story";
import type { Look } from "@/lib/story/looks";
import type { Controls } from "@/lib/story/controls";
import type { Frame } from "./conductor";
import { createFaces } from "./faces";
import { faceMaterial } from "./face-material";
import type { PieceProps, StoryBundle } from "./types";

export const FOV = 38;
export const CAMERA_Z = 12;
export type Pointer = { x: number; y: number };
function Card({ material, look }: PieceProps) {
  // Bias the thin box sides behind printed faces to avoid MSAA edge speckles.
  return <><mesh castShadow receiveShadow frustumCulled={false}><boxGeometry args={[1, 1, 0.045]} /><meshStandardMaterial color={look.surface.color} roughness={look.surface.roughness} polygonOffset polygonOffsetFactor={1} polygonOffsetUnits={1} /></mesh><mesh position={[0, 0, 0.03]} material={material} frustumCulled={false}><planeGeometry args={[1, 1]} /></mesh></>;
}
export function Pieces({ bundle, frameRef, stageRef, pointerRef, formationRef, controls, look, coarse, still, rootRef, onError, children }: {
  bundle: StoryBundle; frameRef: RefObject<Frame>; stageRef: RefObject<Stage>; pointerRef: RefObject<Pointer>;
  formationRef: RefObject<Formation>; controls: Controls; look: Look; coarse: boolean; still: boolean;
  rootRef: RefObject<HTMLDivElement | null>; onError: () => void; children?: ReactNode;
}) {
  const group = useRef<THREE.Group>(null);
  const groups = useRef<(THREE.Group | null)[]>([]);
  const count = bundle.story.pieces;
  const beats = useMemo(() => beatsOf(bundle.story), [bundle.story]);
  const from = useRef(blankFormation(count));
  const to = useRef(blankFormation(count));
  const swung = useRef<Vec3>([0, 0, 0]);
  const projected = useRef([0, 0, 0, 0, 0, 0]);
  const overlayPose = useRef<Pose>({ position: [0, 0, 0], rotation: [0, 0, 0], size: [1, 1] });
  const blank = useMemo(() => {
    const value = look.surface.glows ? 0 : 255;
    const texture = new THREE.DataTexture(new Uint8Array([value, value, value, 255]), 1, 1);
    texture.colorSpace = THREE.SRGBColorSpace; texture.needsUpdate = true; return texture;
  }, [look]);
  const materials = useMemo(() => Array.from({ length: count }, () => faceMaterial(look, blank)), [look, blank, count]);
  const faces = useRef<ReturnType<typeof createFaces> | null>(null);
  const links = useRef<HTMLElement[]>([]);
  useEffect(() => {
    const store = createFaces(bundle.faces, look, coarse);
    faces.current = store;
    links.current = Array.from(rootRef.current?.querySelectorAll<HTMLElement>("[data-story-link]") ?? []);
    return () => { faces.current = null; store.dispose(); for (const link of links.current) { link.style.visibility = "hidden"; link.tabIndex = -1; } };
  }, [bundle.faces, look, coarse, rootRef]);
  useEffect(() => () => { for (const face of materials) face.material.dispose(); blank.dispose(); }, [materials, blank]);

  useFrame(state => {
    const frame = frameRef.current;
    const source = bundle.formations[beats[frame.from].id];
    const target = bundle.formations[beats[frame.to].id];
    const dwell = still ? (frame.dwell < 0.5 ? 0 : 1) : frame.dwell;
    // Resolve the dwell first. Travel leaves the completed within formation.
    atRest(from.current, source, dwell);
    atRest(to.current, target, frame.to === frame.from ? dwell : 0);
    const now = mixFormation(formationRef.current, from.current, to.current, frame.t, frame.each);
    const stage = stageRef.current;
    const caption = lerp(stage.captions[frame.from] ?? 0, stage.captions[frame.to] ?? 0, frame.t);
    const shareX = frame.narrow ? 1 : roomBeside(now.anchor[0]);
    const shareY = frame.narrow ? bandShare(stage.viewport, stage.header, caption) : roomBeside(now.anchor[1]);
    const swing3 = swing(swung.current, from.current, to.current, frame.t, still ? 0.5 : frame.dwell);
    const over = frame.narrow ? 0 : now.over;
    const smaller = over > 0 ? lerp(1, overScale(stage.viewport, stage.header, caption), over) : 1;
    const anchorY = over > 0 ? lerp(now.anchor[1], overAnchor(now.anchor[1], stage.viewport, stage.header, caption), over) : now.anchor[1];
    const fit = frame.narrow ? bandFit(stage.viewport, stage.header, caption) : 1;
    const aspect = state.size.width / state.size.height;
    const z = cameraDistance(now.span, now.rise, aspect, shareX, shareY, FOV, now.near + swing3[2]) / (smaller * (fit || 1));
    state.camera.position.z = z;
    const [halfWidth, halfHeight] = viewHalf(z, FOV, aspect);
    const stack = group.current;
    if (!stack) return;
    stack.visible = fit > 0;
    stack.rotation.set(now.turn[0] + swing3[0] - (still ? 0 : pointerRef.current.y * 0.04), now.turn[1] + swing3[1] + (still ? 0 : pointerRef.current.x * 0.07), 0);
    if (frame.narrow) stack.position.set(0, 2 * halfHeight * stageLift(stage.viewport, stage.header, caption), 0);
    else stack.position.set(now.anchor[0] * halfWidth, anchorY * halfHeight, 0);
    stack.updateMatrix();
    try { faces.current?.draw(); } catch { onError(); return; }
    for (let i = 0; i < count; i++) {
      const piece = groups.current[i];
      const pose = now.pieces[i];
      if (!piece) continue;
      const drift = still ? 0 : Math.sin(frame.time * 0.5 + i) * now.drift * 0.025;
      const lift = !still && controls.get("piece") === i ? 0.025 : 0;
      piece.position.set(pose.position[0], pose.position[1] + drift, pose.position[2] + lift);
      piece.rotation.set(...pose.rotation);
      piece.scale.set(pose.size[0], pose.size[1], 1);
      const store = faces.current;
      if (store) materials[i].set(store.get(beats[frame.from].id, i), store.get(beats[frame.to].id, i), frame.each[i]);
    }
    for (let i = 0; i < (bundle.links?.length ?? 0); i++) {
      const link = links.current[i];
      const def = bundle.links![i];
      if (!link) continue;
      const active = fit > 0 && frame.from === frame.to && beats[frame.from].id === def.beat;
      const mesh = groups.current[def.piece];
      const pose = now.pieces[def.piece];
      if (mesh && pose) {
        overlayPose.current.position[0] = mesh.position.x;
