/bin/bash -lc "cat > checks/spine/transitions.mjs <<'EOF'
import {chromium} from '../../site/node_modules/playwright-core/index.mjs';
import {spawn} from 'node:child_process';
import {writeFile} from 'node:fs/promises';
import assert from 'node:assert/strict';
const server=spawn(process.execPath,[process.cwd()+'/site/node_modules/next/dist/bin/next','start','--hostname','127.0.0.1','--port','3028'],{cwd:process.cwd()+'/site',env:{...process.env,NEXT_TELEMETRY_DISABLED:'1'},stdio:'inherit'});let browser;const results=[];
try{for(let i=0;i<80;i++){try{if((await fetch('http://127.0.0.1:3028')).ok)break}catch{}await new Promise(r=>setTimeout(r,250));}browser=await chromium.launch({args:['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']});for(const look of ['light','dark']){const page=await browser.newPage({viewport:{width:1440,height:900}});const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://127.0.0.1:3028/?look='+look);await page.waitForSelector('canvas');await page.waitForTimeout(1200);const boxes=await page.locator('[data-beat]').evaluateAll(els=>els.map(e=>({top:e.getBoundingClientRect().top+scrollY,height:e.offsetHeight})));const sample=[];for(let i=0;i<boxes.length-1;i++){const depart=boxes[i].top+boxes[i].height-900;for(const t of [.25,.5,.75])sample.push({name:i+'-'+t,top:depart+t*900*.6});}for(const direction of ['forward','reverse'])for(const point of direction==='forward'?sample:[...sample].reverse()){await page.evaluate(y=>scrollTo(0,y),point.top);await page.waitForTimeout(500);await page.screenshot({path:"'`checks/spine/transition-${look}-${direction}-${point.name}.png`});}assert.deepEqual(errors,[]);results.push({look,errors,samples:sample.length*2});await page.close();}}catch(e){results.push({failure:String(e)});process.exitCode=1}finally{await browser?.close();server.kill();await writeFile('"'checks/spine/transition-results.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results,null,2))}
EOF
PLAYWRIGHT_BROWSERS_PATH=/tmp/storyfolio-browser-cache LD_LIBRARY_PATH=/tmp/storyfolio-browser-libs/root/usr/lib/x86_64-linux-gnu XDG_CONFIG_HOME=\""'$PWD/checks/spine/config" XDG_CACHE_HOME="$PWD/checks/spine/cache" node checks/spine/transitions.mjs'
